<script setup lang="ts">
import { computed, ref } from 'vue';
import type { Product, QuoteLine } from '~/types/product';
const {categories,query,category,sort,filtered}=useProductCatalog();
const lines=ref<QuoteLine[]>([]); const drawer=ref(false); const copied=ref(false);
const count=computed(()=>lines.value.length);
function add(p:Product){const old=lines.value.find(x=>x.product.id===p.id); if(old)old.quantity+=p.minOrder; else lines.value.push({product:p,quantity:p.minOrder}); copied.value=false;}
function remove(id:string){lines.value=lines.value.filter(x=>x.product.id!==id);copied.value=false;}
function quantity(id:string,n:number){const x=lines.value.find(v=>v.product.id===id);if(x)x.quantity=Math.max(x.product.minOrder,n);copied.value=false;}
function money(n:number){return new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(n);}
async function copy(){const rows=lines.value.map((x,i)=>`${i+1}. ${x.product.name} — ${x.quantity} ${x.product.unit} — giá tham khảo từ ${money(x.product.priceFrom)}/${x.product.unit}`);const text=['KINGCUP PRICE — YÊU CẦU BÁO GIÁ','',...rows,'','Lưu ý: Giá trong bản demo, cần xác nhận theo quy cách và số lượng thực tế.'].join('\n');try{await navigator.clipboard.writeText(text);copied.value=true;}catch{copied.value=false;}}
function goProducts(){document.querySelector('#products')?.scrollIntoView({behavior:'smooth'});}
useHead({title:'Kingcup Price — Tìm đúng sản phẩm, chọn giá phù hợp',meta:[{name:'description',content:'Tra cứu sản phẩm, tham khảo giá và chuẩn bị danh sách yêu cầu báo giá.'}]});
</script>
